/** 就地剔除 life<=0 的粒子/飘字(保序零分配,2026-08 审计 G9) */
function compactByLife<T extends { life: number }>(list: T[]): void {
  let w = 0;
  for (let r = 0; r < list.length; r++) {
    if (list[r].life > 0) list[w++] = list[r];
  }
  list.length = w;
}

/** 中核/硬核死亡掉落全部物品（Player.DropItems :53398-53470 gemsOnly=false 分支）：
 *  背包+盔甲+染料+杂项装备+杂项染料+三套 Loadout 全部以掉落物形式撒在死亡点
 *  （TryDroppingSingleItem :53480-53496：随机抛射速度由调用方注入），随后发还
 *  铜制起始三件套（:53463-53468 inventory[0]=3507 短剑/[1]=3509 镐/[2]=3506 斧）。
 *  ★掉落前把起始三件 TurnToAir（:53414-53418）——铜短剑/镐/斧**不掉落**只清空。
 *  软核/旅程走 gemsOnly=true 只掉【大宝石】（:53401-53410：1522-1527 六色大宝石+
 *  3643 大琥珀=夺旗 CTF 旗物，非普通宝石）——该族物品本仓未注册（CTF 模式未实装，
 *  引擎级缺口登记），按缺席等价为不掉。 */
/** Shift 批量买档（ItemSlot.GetBulkBuyAmount :2861-2870）：常规货 10；
 *  buyOnce 货架 min(10, 剩余 stack)。CanBulkBuy（:2874-2881）= Shift 按住 */
export function bulkBuyAmount(buyOnceStack?: number): number {
  return buyOnceStack === undefined ? 10 : Math.min(10, buyOnceStack);
}

export function dropInventoryOnDeath(
  inv: import('../items/Inventory').Inventory,
  spawn: (key: string, stack: number) => void,
): void {
  const drop = (slots: Array<{ id: number; stack: number } | null>, starterGate = false) => {
    for (const s of slots) {
      if (!s || s.id === 0 || s.stack <= 0) continue;
      // 槽位存的是内部 id → 先查内部表（自定义物品 key 唯一权威）；
      // VANILLA_ITEM_KEY_BY_ID 以 vanilla id 为键，不能反过来用（内部 id 撞号会掉错物品）
      const key = ITEM_DEFS[s.id]?.key ?? VANILLA_ITEM_KEY_BY_ID[s.id];
      if (!key) continue;
      // 起始三件套 TurnToAir 不掉落（:53414-53418）——★门只在 inventory 主循环；
      // armor/dye/misc/loadouts 逐组无条件 TryDroppingSingleItem（:53421-53441），勿外扩
      if (starterGate) {
        const vid = ITEM_DEFS[s.id]?.vid ?? viIdFromKey(key);
        if (vid === 3507 || vid === 3506 || vid === 3509) { s.stack = 0; continue; }
      }
      spawn(key, s.stack);
    }
  };
  drop(inv.slots, true);
  drop(inv.armor);
  drop(inv.dye);
  drop(inv.miscEquips);
  drop(inv.miscDyes);
  for (const l of inv.loadouts) { drop(l.armor); drop(l.dye); }  // EquipmentLoadout.TryDroppingItems
  inv.slots.fill(null);
  inv.armor.fill(null);
  inv.dye.fill(null);
  inv.miscEquips.fill(null);
  inv.miscDyes.fill(null);
  for (const l of inv.loadouts) { l.armor.fill(null); l.dye.fill(null); }
  // 发还铜制起始三件套（原版 1:1 顺序：[0]短剑 3507 / [1]镐 3509 / [2]斧 3506）
  const starter = [VI_KEY.STARTER.SHORTSWORD, VI_KEY.STARTER.PICK, VI_KEY.STARTER.AXE];
  starter.forEach((key, i) => {
    const id = ITEM_BY_KEY[key];
    if (id !== undefined) inv.slots[i] = { id, stack: 1 };
  });
}

/** NPC 对话框按钮 id（与 ui/NpcDialog.ts NpcButtonId 同形；quest = 渔夫任务交付） */
export type NpcButtonId = 'shop' | 'heal' | 'curse' | 'collect' | 'reforge' | 'hair' | 'quest' | 'plant' | 'happiness' | 'status' | 'close';
/** 按钮通知图标（NPCChatPanel.cs:136-138 interaction.ShowExclamation →
 *  Utils.DrawNotificationIcon 按钮文字右+8px,rotMul=0 无摇摆仅亮度脉冲） */
export interface NpcButton {
  id: NpcButtonId;
  label: string;
  excl?: boolean;
}

/** 造型师理发报价纯式（Main.cs:43198-43211 逐行）：
 *  发型 100000 + 发色 20000 → 折扣 ×0.8 截断（:43208）→ ×PriceAdjustment 截断
 *  （:43210）→ Round(/10000)×10000 取整到金（:43211）。0 改动 = 0（GameUI.Buy 免费） */
export function hairRestylePriceRaw(hairChanged: boolean, colorChanged: boolean,
  discountAvailable: boolean, priceAdjustment: number): number {
  let price = 0;
  if (hairChanged) price += 100000;
  if (colorChanged) price += 20000;
  if (discountAvailable) price = Math.trunc(price * 0.8);
  price = Math.trunc(price * priceAdjustment);
  return cround(price / 10000) * 10000;   // C# Math.Round 默认 ToEven（银行家舍入）
}

