  /** 滚动 FPS（最近 60 帧均值；样本不足返回 null）——F5 调试报告 meta/perf 段 */
  get fps(): number | null {
    const n = this.frameDts.length;
    if (n < 2) return null;
    let sum = 0;
    for (const d of this.frameDts) sum += d;
    return sum / n > 0 ? 1000 / (sum / n) : null;
  }

  /** 私有运行时状态一次性打包（F5 调试报告 systems 段；私有字段只从这里出） */
