        //  case 6164 :50115）——本仓 shootCd 为 ai[0]/localAI[0] 射击槽等价
        if (cw.shoot === 1113) spawned?.armSpawnCooldown(30);
        if (cw.shoot === 1119) spawned?.armSpawnCooldown(45);
