  private homelessSpawnTimeout = 0;
  /** 本夜天幕流星已掷(_canShowMeteorFall 位;入夜重置) */
  private _skyMeteorShown = false;
  /** FTW 巨石雨记账旗（WorldGen._isRainingBoulders :72235——风暴臂窗口状态，
   *  关闭沿触发成就 34 ITS_SHALING_OUTSIDE） */
